package com.prakash.gmcemp.emission.model;import jakarta.persistence.*;import java.time.*;@Entity @Table(name="emission_calculation") public class EmissionCalculation{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private Long shipmentId;private Long routeId;private Double distanceKm;private Double weightTons;private Double emissionFactor;private Double totalCo2Kg;private LocalDateTime calculatedAt;@PrePersist void pre(){calculatedAt=LocalDateTime.now();}public Long getId(){return id;}public Long getShipmentId(){return shipmentId;}public void setShipmentId(Long v){shipmentId=v;}public Long getRouteId(){return routeId;}public void setRouteId(Long v){routeId=v;}public Double getDistanceKm(){return distanceKm;}public void setDistanceKm(Double v){distanceKm=v;}public Double getWeightTons(){return weightTons;}public void setWeightTons(Double v){weightTons=v;}public Double getEmissionFactor(){return emissionFactor;}public void setEmissionFactor(Double v){emissionFactor=v;}public Double getTotalCo2Kg(){return totalCo2Kg;}public void setTotalCo2Kg(Double v){totalCo2Kg=v;}public LocalDateTime getCalculatedAt(){return calculatedAt;}}